import{_ as t,c as a,o as i,ag as o}from"./chunks/framework.DZ_cNctr.js";const s="/docs/screenshots/calibration-section.png",g=JSON.parse('{"title":"Pixel Size and Magnification","description":"Set the pixel size, Z step and magnification when a file leaves them out or gets them wrong. Measurements, the scale bar and 3D follow, and links carry them.","frontmatter":{"title":"Pixel Size and Magnification","description":"Set the pixel size, Z step and magnification when a file leaves them out or gets them wrong. Measurements, the scale bar and 3D follow, and links carry them."},"headers":[],"relativePath":"guides/calibration.md","filePath":"guides/calibration.md"}'),n={name:"guides/calibration.md"};function r(h,e,d,l,m,c){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="pixel-size-and-magnification" tabindex="-1">Pixel Size and Magnification <a class="header-anchor" href="#pixel-size-and-magnification" aria-label="Permalink to &quot;Pixel Size and Magnification&quot;">​</a></h1><p>Most files say how big a pixel is, and many say which objective took them. Some do not, and some get it wrong. Set the right values yourself, and the viewer measures in micrometres.</p><p>Your file is never changed. The values you set live with the image in the viewer, and travel in a shared link.</p><img width="1304" height="498" src="'+s+'" alt="The Calibration section of Image Information for a Philips slide: Pixel size with X and Y in micrometres, From the file under it, and Magnification with Not in the file under it" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"><h2 id="set-them" tabindex="-1">Set Them <a class="header-anchor" href="#set-them" aria-label="Permalink to &quot;Set Them&quot;">​</a></h2><ol><li>Click <strong>Info</strong>, the (i) button in the toolbar, to open <strong>Image Information</strong>.</li><li>Go to <strong>Calibration</strong>, below Metadata.</li><li>Type the values and click <strong>Save Changes</strong>.</li></ol><table tabindex="0"><thead><tr><th>Field</th><th>What it is</th></tr></thead><tbody><tr><td><strong>Pixel size</strong></td><td>X and Y, in µm. An image with planes shows <strong>Voxel size</strong>, with X, Y and Z.</td></tr><tr><td><strong>Magnification</strong></td><td>The objective, such as 20 or 40.</td></tr></tbody></table><p>Under each field you see what the file states, for example &quot;From the file: 0.2269 × 0.2269 × 0.5 µm&quot;, or &quot;Not in the file&quot;.</p><p>A few things make typing quick:</p><ul><li><strong>X fills Y.</strong> Type X and Y follows. It fills Z too, when the image has planes and the file states no Z step.</li><li><strong>Your own value stays.</strong> A field you change by hand stops following X.</li><li><strong>A comma works</strong> as a decimal point: <code>0,25</code> is <code>0.25</code>.</li><li><strong>A wrong value shows red.</strong> Only numbers above 0 count, and <strong>Save Changes</strong> waits until each field is one.</li></ul><p><strong>Use the file&#39;s values</strong> clears your own and goes back to what the file says.</p><h2 id="what-changes" tabindex="-1">What Changes <a class="header-anchor" href="#what-changes" aria-label="Permalink to &quot;What Changes&quot;">​</a></h2><ul><li><strong>Pixel size.</strong> Distances and areas, the scale bar, the zoom bar and the position under the cursor switch to µm. Measurements you already drew update at once. An image whose file had no pixel size measured in pixels before. Now it measures in µm. A length reads in mm from 1 mm, and an area in mm² from 0.1 mm².</li><li><strong>Magnification.</strong> The zoom bar shows it, for example &quot;Zoom: 50% · 20x&quot;.</li><li><strong>Z step.</strong> It shapes the 3D view: the proportions of the volume, volumes in µm³, distances and the Position card. Save while 3D is open and the view reopens at the same place, with the new step. Your labels, structures and annotations stay where they were.</li></ul><p>The Metadata section still shows the file&#39;s own values.</p><h2 id="when-the-3d-view-looks-flat-or-stretched" tabindex="-1">When the 3D View Looks Flat or Stretched <a class="header-anchor" href="#when-the-3d-view-looks-flat-or-stretched" aria-label="Permalink to &quot;When the 3D View Looks Flat or Stretched&quot;">​</a></h2><p>A wrong or missing Z step is common. A volume can look flat as a coin, or stretched like a tower. A file with no units can read as 1 × 1 × 1. Enter the step your microscope used, for example 0.5 µm or 2 µm, and the volume takes its real shape. See <a href="./3d-rendering.html">3D Rendering</a>.</p><h2 id="magnification-is-never-guessed" tabindex="-1">Magnification Is Never Guessed <a class="header-anchor" href="#magnification-is-never-guessed" aria-label="Permalink to &quot;Magnification Is Never Guessed&quot;">​</a></h2><p>The viewer shows a magnification only when the file states it, or when you enter one. A file gives the size of a pixel on the sample, and that alone does not tell which objective took it. So the zoom bar stays without a magnification rather than show a wrong one.</p><h2 id="what-each-format-states" tabindex="-1">What Each Format States <a class="header-anchor" href="#what-each-format-states" aria-label="Permalink to &quot;What Each Format States&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Format</th><th>Pixel size</th><th>Magnification</th></tr></thead><tbody><tr><td><a href="./ome-zarr.html">OME-Zarr</a></td><td>Yes</td><td>When the dataset holds its OME metadata and names an objective, or holds only one</td></tr><tr><td><a href="./ome-tiff.html">OME-TIFF</a></td><td>Yes</td><td>From the objective in the file</td></tr><tr><td><a href="./zeiss-czi.html">Zeiss CZI</a></td><td>Yes</td><td>From the objective the image names, or the only one</td></tr><tr><td><a href="./aperio-svs.html">Aperio SVS</a></td><td>Yes</td><td>Yes</td></tr><tr><td><a href="./hamamatsu-ndpi.html">Hamamatsu NDPI</a></td><td>Yes</td><td>Yes</td></tr><tr><td><a href="./leica-scn.html">Leica SCN</a></td><td>Yes, for each region</td><td>Yes, for each region</td></tr><tr><td><a href="./philips-tiff.html">Philips TIFF</a></td><td>Yes</td><td>No, enter it here</td></tr><tr><td><a href="./akoya-qptiff.html">Akoya QPTIFF</a></td><td>Yes</td><td>Yes</td></tr><tr><td><a href="./mrxs.html">3DHISTECH MRXS</a></td><td>Yes</td><td>Yes</td></tr><tr><td><a href="./dicom-wsi.html">DICOM WSI</a></td><td>Yes</td><td>Yes, unless the finest level was resampled</td></tr></tbody></table><p>Each format&#39;s page says more. A file that leaves a value out still opens. Enter it here.</p><h2 id="share-it" tabindex="-1">Share It <a class="header-anchor" href="#share-it" aria-label="Permalink to &quot;Share It&quot;">​</a></h2><p>A link you copy carries your values, so the person who opens it measures in the same units:</p><table tabindex="0"><thead><tr><th>In the link</th><th>Means</th></tr></thead><tbody><tr><td><code>px=0.25</code></td><td>Pixel size along X, in µm</td></tr><tr><td><code>py=0.26</code></td><td>Pixel size along Y, only when it differs from X</td></tr><tr><td><code>pz=2</code></td><td>Z step, in µm</td></tr><tr><td><code>mag=40</code></td><td>Magnification</td></tr></tbody></table><p>You can add them by hand too. This IDR volume opens with a Z step of 2 µm:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://find-nuclei.github.io/?url=https://uk1s3.embassy.ebi.ac.uk/idr/zarr/v0.4/idr0062A/6001240.zarr&amp;pz=2</span></span></code></pre></div><p>Your values are also saved with the image in the viewer, like your channel settings. Open it again and they are back.</p><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>The screenshot uses <code>Philips-1.tiff</code> from the OpenSlide test data, CC0. See <a href="./../sample-data.html">Sample Data and Credits</a>.</p><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related guides&quot;">​</a></h2><ul><li><a href="./sharing.html">Sharing Views</a></li><li><a href="./3d-rendering.html">3D Rendering</a></li><li><a href="./annotations.html">Annotations</a>, for distances and areas</li><li><a href="./supported-formats.html">Supported Formats</a></li></ul>',31)])])}const u=t(n,[["render",r]]);export{g as __pageData,u as default};
